import sys

def main():
    s = sys.stdin.read().split()[0]
    n = len(s)
    match = [-1] * n
    st = []
    for i, c in enumerate(s):
        if c == '(':
            st.append(i)
        elif c == ')':
            j = st.pop()
            match[j] = i
            match[i] = j
    drop = [False] * n
    for i, c in enumerate(s):
        if c == '(' and i + 1 < n and s[i + 1] == '(' and match[i + 1] == match[i] - 1:
            drop[i] = True
            drop[match[i]] = True
    print(''.join(c for i, c in enumerate(s) if not drop[i]))

